head.script:

		scwin.t_new_onclick = function(e) {
			var row = treeview1.getSelectedIndex();
			if(!row) {
				// 선택된 노드가 없으면 가장 마지막 row에 추가
				row = dataList1.getRowCount();
			}
			dataList1.insertRow(row);
			treeview1.setEditMode(row + 1);
		};

		scwin.t_copy_onclick = function(e) {
			var ret = [];
			var cnt = dataList1.getRowCount();
			for(var i = cnt - 1; i >= 0; i--){
				if(dataList1.getCellData(i, "gover_type") === "T"){
					// 체크된 노드들 각각을 자신의 노드 바로 아래에 복사
					var data = dataList1.getRowJSON(i);
					// data["gover_type"] = "F"; // 복사된 노드가 check상태가 되는것을 원하지 않을 경우 주석 해제
					dataList1.setRowJSON(i + 1, data);
				}
			}
		};

		scwin.t_del_onclick = function(e) {
			var cnt = dataList1.getRowCount();
			for(var i = cnt - 1; i >= 0; i--){
				if(dataList1.getCellData(i, "gover_type") === "T"){
					dataList1.removeRow(i);
					// 현재는 부모 노드를 지우면 자식 노드까지 자동으로 지워지도록 구현함.
					// 자식 노드가 지워지지 않게 하려면 자식 노드들의 depth를 전부 1씩 감소하도록 수정해야 함.
				}
			}
		};

		scwin.treeview1_getCheckedRow = function() {
			// 방법1
			var ret = [];
			var cnt = dataList1.getRowCount();
			for(var i = cnt - 1; i >= 0; i--){
				if(dataList1.getCellData(i, "gover_type") === "T"){
					ret.push(i);
					// 현재는 부모 노드를 지우면 자식 노드까지 자동으로 지워지도록 구현함.
					// 자식 노드가 지워지지 않게 하려면 자식 노드들의 depth를 전부 1씩 감소하도록 수정해야 함.
				}
			}

			// 방법2
			// var checkedIndexes = treeview1.getCheckedIndexes();
			// checkedIndexes.sort(function(lhs, rhs){return rhs - lhs;});
			// for(var i = 0; i < checkedIndexes.length; i++){
			// 	 ret.push(checkedIndexes[i] - 1);
			//}

			return ret;		
		}

		scwin.t_mod_onclick = function(e) {
			treeview1.setEditMode(treeview1.getSelectedIndex());
		};

		scwin.treeview1_oneditend = function(info){
			WebSquare.logger.printLog("index = " + info.index + ", oldValue = " + info.oldValue + ", newValue = " + info.newValue);
		}

        scwin.onpageload = function() {

        }

        scwin.t_get_onclick = function(e) {
            $p.executeSubmission("submission1");
        };

        scwin.submission1_submitdone = function() {
            treeview1.spanAll(true);
        }

        scwin.treeview1_onimageclick = function(value, nodeElem, index) {
            console.log("treeview1_onimageclick", value, nodeElem, index)
        }

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#treeview1_input', 'key-combo', {
			combo: 'Enter'
		});
	}			
	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('treeview1_node_3').innerText == '가설공사';
	}		
	scwin.unitTest = function() {
		//noResult="previous"
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('t_get').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('treeview1_checkbox_3').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('t_mod').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "400");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
